source("smoke_firm_dir/code/fxns/1_paths.R")
library(data.table)
root<-file.path(OUT_DIR,"dynamic_entry_exit")
files<-c(file.path(root,"independent_transitions_2026-11-03/assigned_observations.csv"),file.path(root,"independent_transitions_2026-11-03/bin_definitions_medians.csv"),file.path(root,"constant_marginal_costs_2026-11-03/incumbent_constant_marginal_costs.csv"))
hashes<-tools::md5sum(files)
d<-fread(files[1]);bins<-fread(files[2]);cost<-fread(files[3])
month_latest<-max(d$month)
z<-merge(d[month==month_latest],cost[,.(brand,mc_constant)],by="brand",all.x=TRUE)
z[,`:=`(quality_representative=bins[variable=="quality"][order(state)]$median[quality_state],xi_representative=bins[variable=="xi"][order(state)]$median[xi_state])]
setorder(z,brand)
z[,joint_state:=quality_state+3L*(xi_state-1L)]
stopifnot(nrow(z)>0,nrow(z)<=5L,!anyDuplicated(z$brand),!anyNA(z))
out<-file.path(root,"initial_roster_2026-11-04");dir.create(out,recursive=TRUE,showWarnings=FALSE)
fwrite(z[,.(brand,month,quality_observed=quality,xi_observed=xi,quality_state,xi_state,joint_state,quality_representative,xi_representative,mc_constant)],file.path(out,"initial_roster.csv"))
saveRDS(list(benchmark_month=month_latest,roster=z,cap=5L,initial_vacancies=5L-nrow(z)),file.path(out,"initial_roster_inputs.rds"))
stopifnot(identical(unname(hashes),unname(tools::md5sum(files))))
fwrite(data.table(path=files,md5=unname(hashes)),file.path(out,"input_hashes.csv"))
writeLines(c("Latest observed demand incumbent roster, December 2023: JUUL, NJOY, VUSE; two starting vacancies under cap five.","Annual >7% demand roster retained; not monthly top-five ranking. BREEZE and other fringe brands are not promoted.","Observed quality and xi mapped to previously selected tercile bins and median representatives. MC uses within-firm historical median, not latest monthly MC.","Initial vacancies permit a potential entrant at the first decision date; at most one entrant per month, production next month.","This saves initialization only; no prices, trial payoff parameters or dynamic equilibrium computed.","Checks passed: unique brands, at most five incumbents, complete bin/cost matches, unchanged source hashes."),file.path(out,"README.txt"))
print(z[,.(brand,quality_state,xi_state,quality_representative,xi_representative,mc_constant)])
